const p = $json;

const limpio = (x) => {
  const v = (x ?? '').toString().trim();
  return (v === '' || v === 'NO_TIENE') ? null : v;
};

const nombre = (p.nombre_negocio || 'Mi Negocio').toString().trim();

const base = nombre
  .toLowerCase()
  .normalize('NFD').replace(/[̀-ͯ]/g, '')
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '')
  .slice(0, 28);

const slug = `${base || 'sitio'}-${p.proyecto_id}`;

return {
  json: {
    proyecto_id: p.proyecto_id,
    telefono: p.telefono,
    nombre_negocio: nombre,
    descripcion_servicios: p.descripcion_servicios,
    logo_url: limpio(p.logo_url),
    // La imagen real del logo. Sin esto el analisis de marca no ve nada
    // y la pagina sale con el wordmark generado en vez del logo del cliente.
    logo_base64: p.logo_base64 || null,
    logo_mime: p.logo_mime || null,
    tiene_logo: !!(p.logo_base64 && String(p.logo_base64).length > 100),
    // el analisis de marca lo busca con este nombre
    nombre_respaldo: nombre,
    ubicacion_url: limpio(p.ubicacion_url),
    horarios: limpio(p.horarios),
    telefonos: limpio(p.telefonos),
    redes_sociales: limpio(p.redes_sociales),
    slug,
  }
};

