const d = $('Preparar datos').first().json;

const sistema = 'Eres director de arte y analista de marca. Respondes SOLO JSON valido. Deduces el nombre real de un negocio mexicano y EL color de su marca.';

const L = [];
L.push('Devuelve un JSON con esta forma exacta:');
L.push('{');
L.push('  "nombre_negocio": string,');
L.push('  "confianza_nombre": "alta" | "media" | "baja",');
L.push('  "origen_nombre": "logo" | "descripcion" | "ninguno",');
L.push('  "color_marca": "#RRGGBB",');
L.push('  "tono": string,');
L.push('  "iniciales": string');
L.push('}');
L.push('');
L.push('REGLAS DEL NOMBRE:');
L.push('- Si el logo tiene texto legible, ESE es el nombre. Transcribelo tal cual, respetando acentos.');
L.push('- Si el logo no trae texto, deducelo de la descripcion del negocio.');
L.push('- NUNCA uses un nombre de persona como nombre del negocio.');
L.push('- Maximo 40 caracteres.');
L.push('');
L.push('REGLAS DEL COLOR (leelas bien):');
L.push('- Devuelve UN SOLO color: el que DOMINA la identidad de la marca.');
L.push('- Si hay logo: es el color mas presente del logo, ignorando blancos, negros y grises.');
L.push('  Si el logo es solo blanco y negro, elige el color que mejor le quede al giro.');
L.push('- Si no hay logo: elige el color que mejor represente al giro del negocio.');
L.push('- Que sea un color con vida, ni gris ni casi negro ni casi blanco.');
L.push('- NO devuelvas una paleta. Solo ese color. Los demas tonos se calculan solos.');
L.push('');
L.push('iniciales: 2 o 3 letras del nombre, para un logo de texto si no hay imagen.');
L.push('tono: 3 a 5 palabras, ej. tecnico, confiable, directo.');
L.push('');
L.push('DESCRIPCION DEL NEGOCIO: ' + String(d.descripcion_servicios || '').slice(0, 900));
L.push('NOMBRE DE RESPALDO (poco confiable, viene de WhatsApp): ' + (d.nombre_respaldo || 'ninguno'));
L.push(d.tiene_logo ? 'Te adjunto el logo. Priorizalo sobre todo lo demas.' : 'NO hay logo. Deduce todo de la descripcion.');

const contenido = [{ type: 'text', text: L.join('\n') }];

if (d.tiene_logo) {
  contenido.push({
    type: 'image_url',
    image_url: {
      url: 'data:' + (d.logo_mime || 'image/jpeg') + ';base64,' + d.logo_base64,
      detail: 'high',
    },
  });
}

return [{ json: { openai_body: {
  model: 'gpt-4.1',
  response_format: { type: 'json_object' },
  max_tokens: 400,
  temperature: 0.2,
  messages: [
    { role: 'system', content: sistema },
    { role: 'user', content: contenido },
  ],
} } }];

const d = $('Preparar datos').first().json;

let m = {};
try {
  const raw = $json && $json.choices && $json.choices[0] && $json.choices[0].message
    ? $json.choices[0].message.content : null;
  if (raw) m = JSON.parse(raw);
} catch (e) { m = {}; }

// ============================================================
//  Paleta derivada de UN solo color, no inventada tono por tono.
//  Antes la IA devolvia 10 hexes sueltos y mezclaba familias
//  (oscuros azules + acentos rojos), con el "claro" tan claro que
//  el texto blanco de la plantilla quedaba a 1.12:1. Invisible.
//  Aqui se calcula la rampa y se BUSCA la L que cumple el
//  contraste WCAG de cada tono: 4.5:1 texto, 3:1 boton.
// ============================================================
const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
const hexToRgb = (h) => { const n = parseInt(h.slice(1), 16); return [(n >> 16) & 255, (n >> 8) & 255, n & 255]; };
const rgbToHex = (r, g, b) => '#' + [r, g, b].map((x) => clamp(Math.round(x), 0, 255).toString(16).padStart(2, '0')).join('');

function rgbToHsl(r, g, b) {
  r /= 255; g /= 255; b /= 255;
  const mx = Math.max(r, g, b), mn = Math.min(r, g, b), dd = mx - mn;
  let h = 0;
  if (dd) {
    if (mx === r) h = ((g - b) / dd) % 6;
    else if (mx === g) h = (b - r) / dd + 2;
    else h = (r - g) / dd + 4;
    h = (h * 60 + 360) % 360;
  }
  const l = (mx + mn) / 2;
  return [h, dd ? dd / (1 - Math.abs(2 * l - 1)) : 0, l];
}
function hslToHex(h, s, l) {
  h = ((h % 360) + 360) % 360; s = clamp(s, 0, 1); l = clamp(l, 0, 1);
  const c = (1 - Math.abs(2 * l - 1)) * s;
  const x = c * (1 - Math.abs(((h / 60) % 2) - 1));
  const mm = l - c / 2;
  const t = h < 60 ? [c, x, 0] : h < 120 ? [x, c, 0] : h < 180 ? [0, c, x]
          : h < 240 ? [0, x, c] : h < 300 ? [x, 0, c] : [c, 0, x];
  return rgbToHex((t[0] + mm) * 255, (t[1] + mm) * 255, (t[2] + mm) * 255);
}
function luminancia(hex) {
  const canal = (v) => { v /= 255; return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); };
  const [r, g, b] = hexToRgb(hex);
  return 0.2126 * canal(r) + 0.7152 * canal(g) + 0.0722 * canal(b);
}
function contraste(a, b) {
  const [x, y] = [luminancia(a), luminancia(b)].sort((p, q) => q - p);
  return (x + 0.05) / (y + 0.05);
}
function buscarL(h, s, Lini, fondo, objetivo, dir) {
  let mejor = hslToHex(h, s, Lini);
  if (contraste(mejor, fondo) >= objetivo) return mejor;
  for (let i = 1; i <= 100; i++) {
    const L = clamp(Lini + dir * i * 0.01, 0, 1);
    const c = hslToHex(h, s, L);
    if (contraste(c, fondo) >= objetivo) return c;
    mejor = c;
    if (L === 0 || L === 1) break;
  }
  return mejor;
}

function derivarPaleta(colorMarca) {
  const valido = /^#[0-9a-fA-F]{6}$/.test(String(colorMarca || ''));
  const ref = valido ? colorMarca : '#2563eb';
  const [h0, s0, l0] = rgbToHsl(...hexToRgb(ref));
  const H = h0;
  const S = clamp(s0 || 0.72, 0.45, 0.90);

  // Temperatura de los neutros.
  // Una rampa de un solo tono se ve barata. Las paletas que se ven caras
  // combinan neutros de una temperatura con un acento de la contraria: la
  // plantilla original hacia justo eso (cafe y crema calidos + verde salvia
  // frio). Acento calido pide neutros frios, y al reves.
  const esCalido = (H <= 70 || H >= 300);
  const esFrio   = (H >= 150 && H <= 285);
  const Hn = esCalido ? 215 : esFrio ? 32 : H;
  const Sn = esCalido ? 0.10 : esFrio ? 0.13 : 0.06;

  const oscuro   = hslToHex(Hn, Sn * 1.9, 0.075);
  const oscuro_2 = hslToHex(Hn, Sn * 1.7, 0.12);
  const oscuro_3 = hslToHex(Hn, Sn * 1.5, 0.18);
  const claro    = hslToHex(Hn, Sn * 0.9, 0.975);
  const claro_2  = hslToHex(Hn, Sn * 0.8, 0.945);
  const claro_3  = hslToHex(Hn, Sn * 0.7, 0.90);

  let Lac = clamp(l0, 0.38, 0.58);
  for (let i = 0; i < 60; i++) {
    const c = hslToHex(H, S, Lac);
    if (contraste(c, claro) >= 3.0 && contraste(c, oscuro) >= 3.0) break;
    Lac += contraste(c, claro) < 3.0 ? -0.01 : 0.01;
    Lac = clamp(Lac, 0.20, 0.75);
  }
  const acento = hslToHex(H, S, Lac);

  return {
    oscuro, oscuro_2, oscuro_3, claro, claro_2, claro_3, acento,
    acento_oscuro: buscarL(H, clamp(S * 1.02, 0, 1), clamp(Lac - 0.10, 0.10, 0.60), claro,  4.5, -1),
    acento_claro:  buscarL(H, clamp(S * 0.78, 0, 1), clamp(Lac + 0.20, 0.40, 0.95), oscuro, 4.5, +1),
    neutro:        buscarL(Hn, Sn * 1.2, 0.50, claro, 4.5, -1),
  };
}

const paleta = derivarPaleta(m.color_marca);

// ---------- nombre, iniciales, slug ----------
let nombre = String(m.nombre_negocio || '').trim();
// Cuando la vision no saca nombre del logo se cae al nombre de WhatsApp del
// dueno, que suele ser su nombre de pila, o a "Mi Negocio". Se marca para que
// el copywriter invente uno que si suene a marca.
let nombre_generico = false;
if (!nombre || nombre.length > 60) {
  nombre = d.nombre_respaldo || 'Mi Negocio';
  nombre_generico = true;
}

let iniciales = String(m.iniciales || '').trim().toUpperCase().slice(0, 3);
if (!/^[A-Z0-9]{1,3}$/.test(iniciales)) {
  iniciales = nombre.split(/\s+/).filter(Boolean).slice(0, 2)
    .map((w) => w[0]).join('').toUpperCase().replace(/[^A-Z0-9]/g, '') || 'MN';
}

const base = nombre.toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 28);
const slug_final = (base || 'sitio') + '-' + d.proyecto_id;

return [{ json: {
  ...d,
  slug_final,
  marca: {
    nombre_negocio: nombre,
    nombre_generico,
    confianza_nombre: m.confianza_nombre || 'baja',
    origen_nombre: m.origen_nombre || 'ninguno',
    tono: String(m.tono || '').trim() || 'profesional, claro, confiable',
    iniciales,
    color_marca: /^#[0-9a-fA-F]{6}$/.test(String(m.color_marca || '')) ? m.color_marca.toLowerCase() : null,
    paleta,
  },
} }];

// ============================================================
//  PRUEBA 2 · RESOLVER DISENO
//
//  Aqui se decide TODO el aspecto de la pagina a partir de dos cosas: el
//  logo del negocio y su giro. Nada queda fijo de la plantilla.
//
//  COLOR. Antes solo se cambiaban cuatro acentos y el resto de la pagina
//  seguia siendo negra, viniera de donde viniera el logo. Ahora se calcula
//  una paleta completa -fondo, superficies, texto, bordes, acentos- a partir
//  del color del logo. Si el negocio no mando logo, el color sale del giro.
//
//  CLARO U OSCURO. Tampoco es siempre oscuro. Una clinica o una guarderia en
//  negro se siente fria; una joyeria o un gimnasio en blanco pierde el golpe.
//  Manda el giro, salvo que el color del logo sea un extremo: un color muy
//  palido necesita fondo oscuro para verse, y uno muy oscuro necesita fondo
//  claro. En esos dos casos gana el logo.
//
//  TIPOGRAFIA. Cambia con el giro, pero TODAS son de palo seco y el cuerpo
//  del texto es siempre Roboto: son las que mejor se leen en pantalla y las
//  que no hacen que la pagina parezca hecha por una IA.
// ============================================================
const marca = $('Leer marca').first().json.marca;
const datos = $('Preparar datos').first().json;
const perfil = (() => {
  const p = $('Perfil del negocio (IA)').first().json;
  return p.output ?? p;
})();

// ---------- el nombre ya no se adivina ----------
// El nombre del negocio es dato obligatorio del asistente de ventas y viene
// en la base. Antes se deducia mirando el logo, y cuando el logo no traia
// texto salia el nombre de la persona de WhatsApp como titulo de la pagina.
const nombreReal = String(datos.nombre_negocio || '').trim();
if (nombreReal && nombreReal.toLowerCase() !== 'mi negocio') {
  marca.nombre_negocio = nombreReal;
  marca.nombre_generico = false;
  marca.iniciales = nombreReal.split(/\s+/).filter(Boolean).slice(0, 3)
    .map((w) => w[0]).join('').toUpperCase().replace(/[^A-Z0-9]/g, '').slice(0, 3) || marca.iniciales;
}

// El repositorio de GitHub y el dominio de Vercel llevan el nombre del
// negocio y su giro: "NewFit" + gimnasio -> newfit-gimnasio.
//
// El giro hace dos cosas. Se lee mejor -el cliente ve de que es la pagina
// antes de abrirla- y separa a dos negocios que se llamen parecido, que es
// de donde salian los choques de nombre en Vercel.
const enTrozos = (t) => String(t || '')
  .toLowerCase()
  .normalize('NFD').replace(/[̀-ͯ]/g, '')
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '');

// El nombre va pegado, como antes: "Casana Natural Health" -> casananaturalhealth
const trozoNombre = enTrozos(marca.nombre_negocio).replace(/-/g, '').slice(0, 30);
// Del giro bastan dos palabras: "taller mecanico", "clinica dental".
const trozoGiro = enTrozos(perfil.giro).split('-').filter(Boolean).slice(0, 2).join('-').slice(0, 22);

// El numero SOLO aparece cuando hubo que reintentar, que es justo cuando el
// nombre limpio ya estaba ocupado. En una publicacion normal no se ve.
const intento = (() => {
  try { return Number($('Reservar sitio').first().json.intentos) || 1; } catch (e) { return 1; }
})();

const repo_slug = [trozoNombre || 'sitio', trozoGiro || null, intento > 1 ? intento : null]
  .filter(Boolean).join('-').slice(0, 60).replace(/-+$/, '');

// ---------- utiles de color ----------
const aRgb = (h) => {
  let s = String(h).replace('#', '');
  if (s.length === 3) s = s[0] + s[0] + s[1] + s[1] + s[2] + s[2];
  const n = parseInt(s, 16);
  // Se asigna antes de devolver: el analisis estatico de n8n confunde un
  // `return [` dentro de una funcion auxiliar con la salida del nodo y marca
  // el workflow como invalido, lo que tapa errores de verdad.
  return { r: (n >> 16) & 255, g: (n >> 8) & 255, b: n & 255 };
};
const aHsl = (hex) => {
  const c = aRgb(hex);
  const r0 = c.r / 255, g0 = c.g / 255, b0 = c.b / 255;
  const mx = Math.max(r0, g0, b0), mn = Math.min(r0, g0, b0);
  const l = (mx + mn) / 2;
  if (mx === mn) return { h: 0, s: 0, l };
  const d = mx - mn;
  const s = l > 0.5 ? d / (2 - mx - mn) : d / (mx + mn);
  let h;
  if (mx === r0) h = ((g0 - b0) / d + (g0 < b0 ? 6 : 0)) / 6;
  else if (mx === g0) h = ((b0 - r0) / d + 2) / 6;
  else h = ((r0 - g0) / d + 4) / 6;
  return { h, s, l };
};
const aHex = (h, s, l) => {
  h = ((h % 1) + 1) % 1; s = Math.min(1, Math.max(0, s)); l = Math.min(1, Math.max(0, l));
  const f = (n) => {
    const k = (n + h * 12) % 12;
    const a = s * Math.min(l, 1 - l);
    const v = l - a * Math.max(-1, Math.min(k - 3, Math.min(9 - k, 1)));
    return Math.round(v * 255).toString(16).padStart(2, '0');
  };
  return '#' + f(0) + f(8) + f(4);
};
// contraste WCAG: por debajo de 4.5 el texto chico no se lee
const lum = (hex) => {
  const c = aRgb(hex);
  const g = (v) => { v /= 255; return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); };
  return 0.2126 * g(c.r) + 0.7152 * g(c.g) + 0.0722 * g(c.b);
};
const contraste = (a, b) => {
  const x = Math.max(lum(a), lum(b)), y = Math.min(lum(a), lum(b));
  return (x + 0.05) / (y + 0.05);
};

// ---------- color base del negocio ----------
// Si mando logo, el color sale del logo. Si no, del giro: son colores que
// funcionan para ese tipo de negocio y no salen de un sombrero.
const COLOR_POR_FAMILIA = {
  corporativo: '#1f4e79', lujo: '#8a6d3b', industrial: '#b4531f',
  gastronomia: '#c0392b', tecnologia: '#3d5afe', bienestar: '#2e8b72',
  infantil: '#f2793d', deportes: '#e23b2e', artesanal: '#7d9a4e',
};
const claveFam = String(perfil.familia_visual || '').trim().toLowerCase();
const base = /^#[0-9a-f]{6}$/i.test(String(marca.color_marca || ''))
  ? marca.color_marca
  : (COLOR_POR_FAMILIA[claveFam] || COLOR_POR_FAMILIA.corporativo);
const baseHsl = aHsl(base);
const H = baseHsl.h, S = baseHsl.s, Lbase = baseHsl.l;

// ---------- claro u oscuro ----------
const TEMA_POR_FAMILIA = {
  corporativo: 'claro', bienestar: 'claro', infantil: 'claro', artesanal: 'claro',
  gastronomia: 'oscuro', lujo: 'oscuro', industrial: 'oscuro',
  tecnologia: 'oscuro', deportes: 'oscuro',
};
let tema = TEMA_POR_FAMILIA[claveFam] || 'claro';
let porQueTema = 'por el giro (' + (claveFam || 'sin familia') + ')';
if (Lbase >= 0.78) { tema = 'oscuro'; porQueTema = 'el color del logo es muy palido y necesita fondo oscuro'; }
else if (Lbase <= 0.20) { tema = 'claro'; porQueTema = 'el color del logo es muy oscuro y se perderia en fondo negro'; }

// ---------- la paleta completa ----------
// La plantilla trae SU PROPIO sistema de temas, hecho a conciencia: un juego
// de variables por defecto, otro dentro de @media (prefers-color-scheme) y un
// tercero, --photo-*, para las zonas que van sobre fotografia (hero, header,
// cargador, visor y franjas). Esas ultimas no cambian nunca, porque debajo
// siempre hay una foto oscurecida y el texto va claro pase lo que pase.
//
// Asi que aqui no se invierte nada a mano: se calculan las DOS paletas de
// marca -la clara y la oscura- y cada una se escribe en el bloque que le toca.
// Trabajar con la estructura de la plantilla en vez de contra ella.
//
// Los neutros llevan un toque del tono de la marca (saturacion muy baja): un
// gris puro al lado de un color de marca se ve apagado y barato.
const Sn = Math.min(0.10, 0.03 + S * 0.10);
const Sac = Math.max(S, 0.42);

// Mueve la luminosidad de un color hasta que se lea sobre su fondo, sin
// cambiarle el tono: el resultado es el mas parecido al de la marca que si
// pasa. Se apunta por encima del 4.5 de la norma porque estos colores tambien
// caen sobre paneles y pastillas tintadas, no solo sobre el fondo liso.
//
// Barrer desde un extremo y quedarse con el primero que contrastara daba, para
// un logo rojo #c62828, un rosa palido #eeaaaa: contrastaba perfecto y no se
// parecia en nada al negocio.
const ajusta = (hue, sat, l0, min, fondo, osc) => {
  const paso = osc ? 0.02 : -0.02;   // en tema oscuro aclara, en claro oscurece
  let mejor = aHex(hue, sat, l0), mejorC = contraste(mejor, fondo);
  for (let i = 0; i <= 45; i++) {
    const l = l0 + paso * i;
    if (l < 0.12 || l > 0.90) break;
    const c = aHex(hue, sat, l);
    const k = contraste(c, fondo);
    if (k > mejorC) { mejorC = k; mejor = c; }
    if (k >= min) return c;
  }
  return mejor;
};

const paletaDe = (osc) => {
  const L = {
    fondo:   osc ? 0.055 : 0.985,
    fondo_2: osc ? 0.095 : 0.960,
    fondo_3: osc ? 0.145 : 0.925,
    texto:   osc ? 0.965 : 0.105,
    texto_2: osc ? 0.720 : 0.380,
    linea:   osc ? 0.230 : 0.860,
  };
  const c = {
    fondo:   aHex(H, Sn, L.fondo),
    fondo_2: aHex(H, Sn, L.fondo_2),
    fondo_3: aHex(H, Sn * 1.2, L.fondo_3),
    texto:   aHex(H, Sn * 0.6, L.texto),
    texto_2: aHex(H, Sn, L.texto_2),
    linea:   aHex(H, Sn, L.linea),
  };
  // Los acentos se calibran contra fondo_3, que es la superficie mas
  // desfavorable de la pagina: los paneles y las tarjetas son mas claros que
  // el fondo en tema oscuro, y mas oscuros en tema claro. Contra el fondo liso
  // las pastillas de categoria, que van sobre un panel, se quedaban cortas.
  c.superficie = c.fondo_3;
  c.acento = ajusta(H, Sac, Lbase, 4.8, c.superficie, osc);
  const Lac = aHsl(c.acento).l;
  c.acento_oscuro = aHex(H, Math.min(1, S * 1.05 + 0.05), Math.max(0.12, Lac - 0.14));
  c.acento_claro = aHex(H, Math.max(0.25, S * 0.75), Math.min(0.92, Lac + 0.22));
  // El texto que va ENCIMA del acento (botones): blanco o negro, el que gane.
  c.sobre_acento = contraste('#ffffff', c.acento) >= contraste('#111111', c.acento)
    ? '#ffffff' : '#111111';
  // Detalle y apoyo: tonos vecinos del de la marca, no colores al azar.
  c.detalle = ajusta(H + 0.085, Math.max(0.30, S * 0.8), osc ? 0.62 : 0.42, 5.0, c.superficie, osc);
  c.apoyo = ajusta(H - 0.085, Math.max(0.22, S * 0.6), osc ? 0.55 : 0.40, 5.0, c.superficie, osc);
  return c;
};

const osc = tema === 'oscuro';
const colorOscuro = paletaDe(true);
const colorClaro = paletaDe(false);
const color = osc ? colorOscuro : colorClaro;

// ---------- tipografia ----------
// La escogen un agente propio mirando el logo y el giro, y este codigo. El
// agente pone los NOMBRES; los pesos los pone la tabla de abajo, porque cada
// familia de Google tiene su propio rango y pedir un peso que no existe hace
// que la API responda 400 y la pagina se quede con la fuente del sistema.
//
// Y no se le cree a ciegas: se comprueba que cada fuente este en el catalogo
// y que sirva para el papel que le toca. Si el agente inventa un nombre, o
// pone una serif de titulares como fuente de cuerpo, se cae al trio del giro.
// Eso es lo que evita la "tipografia de IA" que se nota a un kilometro.
//
// Tres papeles, como en cualquier landing bien hecha:
//   display  los titulares grandes. Es la que da caracter.
//   texto    parrafos, menus y botones. Manda la legibilidad, no el estilo.
//   acento   las etiquetas chicas en mayusculas (eyebrows, categorias,
//            rotulos). Es el tercer nivel que separa una pagina cuidada de
//            una hecha con una sola fuente.
const TIPOS = {
  // --- serif con caracter: lujo, belleza, joyeria, bufetes, hoteleria ---
  'Playfair Display': { pesos: '500;600;700;800', papeles: 'display' },
  'Cormorant Garamond': { pesos: '500;600;700', papeles: 'display' },
  'Lora': { pesos: '500;600;700', papeles: 'display texto' },
  'Fraunces': { pesos: '500;600;700;900', papeles: 'display' },
  'Bitter': { pesos: '500;600;700', papeles: 'display texto' },
  'Libre Baskerville': { pesos: '400;700', papeles: 'display' },
  'Spectral': { pesos: '500;600;700', papeles: 'display texto' },

  // --- sans con personalidad: tecnologia, agencias, moda, arquitectura ---
  'Jost': { pesos: '500;600;700', papeles: 'display acento' },
  'Poppins': { pesos: '500;600;700', papeles: 'display' },
  'Space Grotesk': { pesos: '500;600;700', papeles: 'display acento' },
  'Outfit': { pesos: '500;600;700', papeles: 'display' },
  'Sora': { pesos: '500;600;700', papeles: 'display' },
  'Archivo': { pesos: '500;600;700', papeles: 'display acento' },

  // --- condensadas y fuertes: talleres, gimnasios, construccion, deportes ---
  'Oswald': { pesos: '500;600;700', papeles: 'display acento' },
  'Barlow Condensed': { pesos: '500;600;700', papeles: 'display acento' },
  'Anton': { pesos: '400', papeles: 'display' },
  'Archivo Narrow': { pesos: '500;600;700', papeles: 'display acento' },

  // --- redondeadas y amables: infantil, mascotas, reposteria, guarderias ---
  'Nunito': { pesos: '600;700;800', papeles: 'display texto' },
  'Baloo 2': { pesos: '500;600;700;800', papeles: 'display' },
  'Quicksand': { pesos: '500;600;700', papeles: 'display' },

  // --- de cuerpo: legibles a 16px, que es donde se juega la lectura ---
  'Inter': { pesos: '300;400;500;600;700', papeles: 'texto acento display' },
  'Roboto': { pesos: '300;400;500;700', papeles: 'texto' },
  'Open Sans': { pesos: '300;400;500;600;700', papeles: 'texto' },
  'Source Sans 3': { pesos: '300;400;500;600;700', papeles: 'texto' },
  'Work Sans': { pesos: '300;400;500;600;700', papeles: 'texto acento' },
  'Nunito Sans': { pesos: '300;400;500;600;700', papeles: 'texto' },
  'Karla': { pesos: '300;400;500;600;700', papeles: 'texto acento' },
  'Lato': { pesos: '300;400;700', papeles: 'texto' },
  'Barlow': { pesos: '300;400;500;600;700', papeles: 'texto' },
  'Rubik': { pesos: '300;400;500;600;700', papeles: 'texto display acento' },
  'Manrope': { pesos: '300;400;500;600;700', papeles: 'texto acento' },
  'IBM Plex Sans': { pesos: '300;400;500;600;700', papeles: 'texto acento' },
};

// Las serif necesitan respaldo serif: si Google no carga y caen en Arial, la
// pagina cambia de cara por completo.
const SERIF = /Playfair|Cormorant|Lora|Fraunces|Bitter|Baskerville|Spectral/;

// El trio de respaldo por giro, para cuando el agente falla o no contesta.
const POR_DEFECTO = {
  corporativo: { display: 'Inter', texto: 'Inter', acento: 'Inter' },
  lujo: { display: 'Cormorant Garamond', texto: 'Inter', acento: 'Jost' },
  industrial: { display: 'Oswald', texto: 'Barlow', acento: 'Barlow Condensed' },
  gastronomia: { display: 'Fraunces', texto: 'Rubik', acento: 'Archivo' },
  tecnologia: { display: 'Space Grotesk', texto: 'Inter', acento: 'Space Grotesk' },
  bienestar: { display: 'Lora', texto: 'Nunito Sans', acento: 'Inter' },
  infantil: { display: 'Baloo 2', texto: 'Nunito', acento: 'Nunito' },
  deportes: { display: 'Barlow Condensed', texto: 'Barlow', acento: 'Oswald' },
  artesanal: { display: 'Bitter', texto: 'Karla', acento: 'Karla' },
};
const respaldo = POR_DEFECTO[claveFam] || POR_DEFECTO.corporativo;

const tipo = (() => {
  try { const x = $('Tipografia (IA)').first().json; return x.output ?? x; } catch (e) { return {}; }
})();
let deAgente = 0;
const valida = (nombre, papel, alt) => {
  const n = String(nombre || '').trim();
  const t = TIPOS[n];
  if (t && t.papeles.indexOf(papel) >= 0) { deAgente++; return n; }
  return alt;
};
const fDisplay = valida(tipo.display, 'display', respaldo.display);
const fTexto = valida(tipo.texto, 'texto', respaldo.texto);
const fAcento = valida(tipo.acento, 'acento', respaldo.acento);

// Una sola peticion a Google, con cada familia UNA vez y con sus pesos
// unidos: repetir una familia en la misma URL tambien devuelve 400.
const pesos = {};
for (const par of [[fDisplay, 'display'], [fTexto, 'texto'], [fAcento, 'acento']]) {
  const lista = ((TIPOS[par[0]] || {}).pesos || '400;700').split(';');
  pesos[par[0]] = pesos[par[0]] ? pesos[par[0]].concat(lista) : lista;
}
const familias = Object.keys(pesos).map((n) => 'family=' + n.replace(/\s+/g, '+')
  + ':wght@' + [...new Set(pesos[n])].map(Number).sort((a, b) => a - b).join(';'));
const linkFuentes = '<link rel="preconnect" href="https://fonts.googleapis.com">'
  + '<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>'
  + '<link rel="stylesheet" href="https://fonts.googleapis.com/css2?'
  + familias.join('&') + '&display=swap">';
const pila = (n) => '"' + n + '",'
  + (SERIF.test(n) ? 'Georgia,"Times New Roman",serif'
    : 'system-ui,-apple-system,"Segoe UI",Roboto,Arial,sans-serif');

return [{
  json: {
    ...$('Leer marca').first().json,
    marca,
    repo_slug,
    perfil,
    diseno: {
      familia_visual: POR_DEFECTO[claveFam] ? claveFam : 'corporativo',
      tema,
      por_que_tema: porQueTema,
      color_base: base,
      color_origen: /^#[0-9a-f]{6}$/i.test(String(marca.color_marca || '')) ? 'logo' : 'giro',
      fuente_display: fDisplay,
      fuente_texto: fTexto,
      fuente_acento: fAcento,
      // cuantas de las tres escogio el agente y cuantas se cayeron al respaldo
      tipografia_del_agente: deAgente + ' de 3',
      tipografia_por_que: String(tipo.por_que || '').slice(0, 240),
      pila_display: pila(fDisplay),
      pila_texto: pila(fTexto),
      pila_acento: pila(fAcento),
      link_fuentes: linkFuentes,
      color,
      color_oscuro: colorOscuro,
      color_claro: colorClaro,
    },
  },
}];

// ============================================================
//  PRUEBA 2 · PREPARAR CONTEXTO
//
//  Lo que necesitan varios bloques y no pertenece a ninguno: el logo, los
//  datos de contacto y la lista de fotos. Se resuelve una vez aqui para que
//  ningun bloque tenga que adivinar.
// ============================================================
const d = $('Preparar datos').first().json;
const j = $('Resolver diseno').first().json;
const marca = j.marca;
const P = marca.paleta;

// ---------- logo ----------
// El logo va como ARCHIVO del repo, no incrustado en el HTML.
//
// La plantilla lo usa SEIS veces -cabecera, pantalla de carga, pie, ventana
// de WhatsApp...- y cuando iba como data URI esas seis copias eran la misma
// imagen repetida: un logo normal de 289 KB en base64 dejaba la pagina en
// 1.8 MB, el 93% de ella la misma foto. No pasaba la revision, y de haber
// pasado habria tardado una eternidad en abrir con datos moviles.
//
// Como archivo el navegador lo baja una vez y lo reutiliza en los seis
// sitios. Sin logo del cliente se dibuja un monograma en SVG con el color de
// la marca, que pesa medio kilobyte y deja mejor cara que un hueco.
const escXml = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;')
  .replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&apos;');

const EXTENSION = {
  'image/png': 'png', 'image/jpeg': 'jpg', 'image/jpg': 'jpg',
  'image/webp': 'webp', 'image/gif': 'gif', 'image/svg+xml': 'svg',
};

let logo_src;
let logo_b64;
if (d.logo_base64) {
  logo_src = 'logo.' + (EXTENSION[String(d.logo_mime || '').toLowerCase()] || 'jpg');
  logo_b64 = d.logo_base64;
} else {
  const ini = escXml(marca.iniciales || 'MN');
  const svg = '<svg xmlns="http://www.w3.org/2000/svg" width="120" height="120" viewBox="0 0 120 120">'
    + '<rect width="120" height="120" rx="30" fill="' + P.acento + '"/>'
    + '<text x="60" y="62" font-family="system-ui,-apple-system,Segoe UI,Arial,sans-serif"'
    + ' font-size="46" font-weight="700" fill="' + P.claro + '"'
    + ' text-anchor="middle" dominant-baseline="middle">' + ini + '</text></svg>';
  logo_src = 'logo.svg';
  logo_b64 = Buffer.from(svg, 'utf8').toString('base64');
}

// ---------- contacto ----------
const tel = String(d.telefono || '').replace(/\D/g, '');
const wa = 'https://wa.me/' + tel;
const redes = d.redes_sociales
  ? String(d.redes_sociales).split(/[\s,;]+/).filter((x) => /^https?:\/\//.test(x))
  : [];
const buscar = (f) => redes.find((u) => u.toLowerCase().includes(f)) || wa;

// El numero se enseña legible, no como una tira de trece digitos. En Mexico
// los numeros van 10 digitos despues del 52, y el 1 de movil no se escribe.
const bonito = (t) => {
  const n = t.replace(/^521?/, '');
  return n.length === 10 ? n.replace(/(\d{3})(\d{3})(\d{4})/, '$1 $2 $3') : (t || '');
};

// ---------- sucursales y telefonos ----------
// El cliente puede tener varios locales y varios numeros. El asistente no se
// los pide, pero si los menciona quedan guardados y aqui se separan para que
// salgan TODOS en la pagina.
//
// Se corta por salto de linea, punto y coma y vineta. A proposito NO se corta
// por " y " ni por coma: "Av. Obregon 123, Col. Centro" es UNA direccion, y
// partirla ahi dejaria media calle en cada renglon.
const enPartes = (t) => String(t || '')
  .split(/\r?\n|;|\u2022|\s\|\s/)
  .map((x) => x.replace(/^[\s\-*\u2013\u2014]+/, '').replace(/^\d+[.)]\s*/, '').trim())
  .filter((x) => x && x.toUpperCase() !== 'NO_TIENE');

// Cada sucursal lleva el texto que se ensena y la consulta que va a Maps. Si
// el cliente mando un link de Maps en vez de escribir la direccion, el link
// es la consulta y no hay texto que ensenar.
const sucursales = enPartes(d.ubicacion_url).slice(0, 6).map((parte) => {
  const soloLink = /^https?:\/\/\S+$/.test(parte);
  return { texto: soloLink ? '' : parte, mapa: parte };
}).filter((s) => s.texto || s.mapa);

// De los telefonos se sacan las tiras de digitos. El numero por el que
// escribe el cliente ya sale como WhatsApp, asi que no se repite.
// Linea por linea: si se buscara sobre el texto entero, el espacio en
// blanco de la expresion incluiria el salto de linea y dos numeros en dos
// renglones se leerian como uno solo de veinte digitos.
const digitos = (x) => String(x).replace(/\D/g, '');
const telefonos = [...new Set(enPartes(d.telefonos)
  .map((linea) => {
    const m = linea.match(/\+?\d[\d ().-]{7,}\d/);
    return m ? digitos(m[0]) : '';
  })
  .filter(Boolean))]
  .filter((t) => t.length >= 10 && t.replace(/^521?/, '') !== tel.replace(/^521?/, ''))
  .slice(0, 5);

// ---------- fotos ----------
// Dos busquedas con angulos distintos, intercaladas: con una sola, las doce
// fotos de la pagina salen casi identicas y se nota el banco de imagenes.
const urlsDe = (nodo) => {
  try {
    const px = $(nodo).first().json;
    return (px && px.photos ? px.photos : [])
      .map((f) => (f.src && (f.src.large || f.src.landscape || f.src.original)) || null)
      .filter(Boolean);
  } catch (e) { return []; }
};
const a = urlsDe('Buscar fotos (Pexels)');
const b = urlsDe('Buscar fotos 2 (Pexels)');
const fotos = [];
for (let i = 0; i < Math.max(a.length, b.length); i++) {
  if (a[i]) fotos.push(a[i]);
  if (b[i]) fotos.push(b[i]);
}
const unicas = [...new Set(fotos)];
if (!unicas.length) throw new Error('Pexels no devolvio ninguna foto. Sin imagenes la pagina no se publica.');

// Reparto explicito. Antes cada bloque tomaba fotos[0], fotos[1]... por su
// cuenta y dos secciones acababan con la misma imagen sin que nadie lo
// notara. Aqui se decide una sola vez quien usa cual, y si no alcanzan se
// repiten en el orden menos visible: la galeria antes que el hero.
const toma = (i) => unicas[i % unicas.length];
const reparto = {
  hero: toma(0),                                  // fondo de la portada, la mas vista
  servicios: [toma(1), toma(2), toma(3)],
  banner1: toma(4),
  resultados: [toma(5), toma(6)],
  banner2: toma(7),
  ventajas: toma(8),                              // fondo de la seccion de ventajas
  contacto: toma(9),                              // fondo de la seccion de contacto
  // La galeria pide seis y son seis mosaicos con lightbox indexado: ni uno
  // mas ni uno menos, o los indices del visor dejan de cuadrar.
  galeria: [toma(10), toma(11), toma(12), toma(13), toma(14), toma(15)],
};

return [{
  json: {
    ...j,
    logo_src,
    // lo que sube 'GitHub subir logo' junto al index.html
    logo_b64,
    enlaces: { instagram: buscar('instagram'), facebook: buscar('facebook'), whatsapp: wa },
    contacto: {
      whatsapp: tel,
      tel_display: bonito(tel),
      // La primera sucursal sigue siendo 'la' ubicacion: es la que va al mapa
      // y la que usan los bloques que solo esperan una.
      ubicacion_texto: sucursales.length ? sucursales[0].texto : '',
      sucursales,
      telefonos,
      // El horario que dio el cliente. Antes llegaba vacio siempre y la
      // pagina acababa con un horario inventado.
      horario: String(d.horarios || '').trim(),
    },
    fotos: unicas,
    reparto,
  },
}];

// ============================================================
//  PRUEBA 2 · TROCEAR PLANTILLA
//
//  El flujo anterior armaba la pagina de un golpe: un nodo de 85 KB que
//  recibia el JSON entero de la IA y rellenaba trescientos huecos a la vez.
//  Cuando algo salia mal no habia forma de saber que seccion lo rompio.
//
//  Aqui la pagina se arma por bloques. Este nodo parte la plantilla en sus
//  piezas y cada bloque se rellena despues por separado, con su propio copy
//  y su propia revision. Si el hero queda mal, se arregla el hero y ya.
//
//  Una sola plantilla: 2-extra. No hay catalogo ni eleccion.
// ============================================================
const tpl = $('Cargar plantilla elegida').first().json;
const html = String(tpl.html || '');
if (!html) throw new Error('La plantilla 2-extra no trae html. Revisa la tabla plantillas.');

// Corta desde un marcador hasta el cierre de su etiqueta, contando las
// anidadas para no quedarse en el primer </div> que aparezca.
const trozo = (marcador, etiqueta, desde) => {
  const i = html.indexOf(marcador, desde || 0);
  if (i < 0) return { txt: '', fin: desde || 0 };
  const re = new RegExp('<(/?)' + etiqueta + '\\b', 'gi');
  re.lastIndex = i + marcador.length;
  let n = 1, m;
  while ((m = re.exec(html)) !== null) {
    n += m[1] ? -1 : 1;
    if (n === 0) {
      const c = html.indexOf('>', m.index);
      return { txt: html.slice(i, c + 1), fin: c + 1 };
    }
  }
  return { txt: '', fin: i };
};

const M_NAV = '<header class="site-header"';
const nav = trozo(M_NAV, 'header');
const hero = trozo('<section class="hero" id="inicio">', 'section');
const servicios = trozo('<section class="services" id="servicios">', 'section');
// Los marcadores van por PREFIJO, sin cerrar la comilla de la clase: la
// plantilla anade clases y atributos a varias secciones (has-bg, --alt,
// data-parallax) y un marcador con la clase cerrada deja de encontrarlas.
const banner1 = trozo('<section class="parallax-banner', 'section');
const ventajas = trozo('<section class="why-us', 'section');
const resultados = trozo('<section class="brochures">', 'section');
const banner2 = trozo('<section class="parallax-banner', 'section', banner1.fin);
const galeria = trozo('<section class="gallery" id="galeria">', 'section');
const contacto = trozo('<section class="contact', 'section');
const footer = trozo('<footer class="site-footer">', 'footer');

// cabeza: todo lo de arriba del header (doctype, head, pantalla de carga)
const cabeza = html.slice(0, html.indexOf(M_NAV));
// flotantes: del boton de WhatsApp hasta justo antes del <script>
const iFlot = html.indexOf('<button type="button" class="whatsapp-float"');
const iScript = html.indexOf('<script', iFlot);
const flotantes = iFlot >= 0 && iScript > iFlot ? html.slice(iFlot, iScript) : '';
const pie = iScript >= 0 ? html.slice(iScript) : '</body></html>';
// lo que queda entre el header y el hero, y entre contacto y footer: <main> y </main>
const abreMain = html.slice(nav.fin, html.indexOf('<section class="hero"'));
const cierraMain = html.slice(contacto.fin, html.indexOf('<footer class="site-footer"'));

const piezas = { cabeza, nav: nav.txt, abreMain, hero: hero.txt, servicios: servicios.txt,
  banner1: banner1.txt, ventajas: ventajas.txt, resultados: resultados.txt, banner2: banner2.txt,
  galeria: galeria.txt, contacto: contacto.txt, cierraMain, footer: footer.txt, flotantes, pie };

// El corte tiene que ser exacto: si al pegar las piezas no sale la plantilla
// original, algo se perdio o se duplico y mas vale enterarse aqui que cuando
// el cliente abra su pagina con media seccion de menos.
const ORDEN = ['cabeza', 'nav', 'abreMain', 'hero', 'servicios', 'banner1', 'ventajas',
  'resultados', 'banner2', 'galeria', 'contacto', 'cierraMain', 'footer', 'flotantes', 'pie'];
const pegado = ORDEN.map((k) => piezas[k]).join('');
if (pegado.replace(/\s+/g, '') !== html.replace(/\s+/g, '')) {
  const vacias = ORDEN.filter((k) => !String(piezas[k]).trim());
  throw new Error('El troceado no reconstruye la plantilla. Piezas vacias: '
    + (vacias.join(', ') || 'ninguna') + '. Original ' + html.length + ' car, pegado ' + pegado.length + '.');
}

// cuantos huecos trae cada pieza, para que la revision final sepa que esperar
const huecosDe = (t) => [...new Set([...String(t).matchAll(/\{\{([A-Z_0-9]+)\}\}/g)].map((m) => m[1]))];
const huecos = {};
for (const k of ORDEN) huecos[k] = huecosDe(piezas[k]);

return [{
  json: {
    ...$('Preparar contexto').first().json,
    piezas,
    orden: ORDEN,
    huecos,
    css: String(tpl.css || ''),
    js: String(tpl.js || ''),
    bloques: {},
  },
}];

// ============================================================
//  PRUEBA 2 · BLOQUE 1 de 9: CABEZA
//
//  El <head>, los metadatos y la pantalla de carga. Aqui entra la tipografia
//  que escogio el resolver de diseno: se tira el link de fuentes que traia la
//  plantilla y se pone el del par elegido.
// ============================================================
// El estado acumulado viene del bloque anterior POR NOMBRE, no de $json:
// entre un bloque y otro hay agentes de IA que reemplazan el item y se
// llevarian por delante piezas, bloques y todo lo demas.
const j = $('Trocear plantilla').first().json;
const D = j.diseno;
const marca = j.marca;
const portada = (() => { const p = $('Copy portada (IA)').first().json; return p.output ?? p; })();

// --- utiles del bloque (van en cada nodo: los Code de n8n no comparten codigo) ---
const sinEmoji = (s) => String(s == null ? '' : s)
  .replace(/[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{2B00}-\u{2BFF}\u{FE00}-\u{FE0F}\u{1F1E6}-\u{1F1FF}]/gu, '')
  .replace(/\s{2,}/g, ' ').trim();
// Cortar en la ultima palabra que cabe deja textos a medio decir -"Algo rico
// para cada quien, sin importar lo que se"- y eso se lee peor que un renglon
// de mas. Aqui se arma el texto con FRASES enteras: se van sumando mientras
// quepan en el hueco mas un 25%, que es mas o menos un renglon y el diseno lo
// acomoda sin despeinarse. La primera frase entra siempre, aunque sea larga:
// media idea nunca se ve bien. Solo un texto desbocado se recorta.
const corta = (s, max) => {
  s = sinEmoji(s);
