    r += f;
  }
  r = r.trim();
  if (r && r.length <= max * 2) return r;
  const largo = r || s;
  const c = largo.slice(0, holgado), e = c.lastIndexOf(' ');
  return (e > 0 ? c.slice(0, e) : c).replace(/[\s,;:.\-]+$/, '');
};
const esc = (s) => sinEmoji(s).replace(/&/g, '&amp;').replace(/</g, '&lt;')
  .replace(/>/g, '&gt;').replace(/"/g, '&quot;');

let h = j.piezas.servicios;
