  pon('GAL_' + i, alts[i - 1] || ((j.perfil.giro || 'Trabajo') + ' ' + i), 60);
}

return [{ json: { ...j, bloques: { ...j.bloques, galeria: h } } }];

// ============================================================
//  PRUEBA 2 · BLOQUE 8 de 9: CONTACTO
//
//  Datos reales, botones de accion y mapa. Aqui no hay copy que inventar: el
//  telefono, la direccion y el horario son del cliente o no van.
//
//  La seccion trae tres renglones con icono —ubicacion, WhatsApp y horario— y
//  cada uno lleva su etiqueta chica. Esas etiquetas reutilizan los huecos
//  ETIQ_2 y ETIQ_3, que en las franjas de mas arriba significan otra cosa;
