const portada = (() => { const p = $('Copy portada (IA)').first().json; return p.output ?? p; })();
const cierre = (() => { const p = $('Copy cierre (IA)').first().json; return p.output ?? p; })();

const sinEmoji = (s) => String(s == null ? '' : s)
  .replace(/[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{2B00}-\u{2BFF}\u{FE00}-\u{FE0F}\u{1F1E6}-\u{1F1FF}]/gu, '')
  .replace(/\s{2,}/g, ' ').trim();
