  if (s.length <= holgado) return s;
  const frases = s.match(/[^.!?;]+[.!?;]+\s*/g) || [];
  let r = '';
  for (const f of frases) {
    if (r && (r + f).trim().length > holgado) break;
    r += f;
  }
  r = r.trim();
  if (r && r.length <= max * 2) return r;
  const largo = r || s;
  const c = largo.slice(0, holgado), e = c.lastIndexOf(' ');
  return (e > 0 ? c.slice(0, e) : c).replace(/[\s,;:.\-]+$/, '');
};
const esc = (s) => sinEmoji(s).replace(/&/g, '&amp;').replace(/</g, '&lt;')
  .replace(/>/g, '&gt;').replace(/"/g, '&quot;');

let h = j.piezas.contacto;
const c = cierre.contacto || {};
const pon = (tok, val, max) => { h = h.split('{{' + tok + '}}').join(esc(corta(val, max))); };

// ---------- varias sucursales y varios telefonos ----------
// Se clonan los renglones que ya trae la plantilla en vez de escribir HTML
// nuevo: asi el icono, las clases y la animacion de entrada salen de ahi.
// Va ANTES de rellenar los tokens, porque el molde los necesita todavia sin
// sustituir para poder darle a cada copia su propio valor.
// `dentro` impide que el molde se salte un </li>: sin eso, el del telefono
// arrancaba en el primer renglon de la lista y se llevaba por delante los de
// las sucursales, que salian duplicadas.
const dentro = '(?:(?!<\\/li>)[\\s\\S])*?';
const LI_UBICACION = new RegExp('<li data-reveal>' + dentro + 'maps\\/search' + dentro + '<\\/li>');
const LI_TELEFONO = new RegExp('<li data-reveal>' + dentro + 'wa\\.me\\/\\{\\{WHATSAPP\\}\\}' + dentro + '<\\/li>');

const sucursales = j.contacto.sucursales || [];
const telefonos = j.contacto.telefonos || [];

if (sucursales.length) {
  const molde = h.match(LI_UBICACION);
  if (molde) {
    const filas = sucursales.map((s, i) => {
      // Mucha gente manda el link de Google Maps sin escribir la direccion.
      // Entonces el enlace va directo al link que dio, y el renglon se queda
      // sin la linea de texto en vez de rellenarla con un "Ver ubicacion"
      // que no dice nada.
      const esLink = /^https?:\/\//i.test(s.mapa);
      const destino = esLink
        ? s.mapa
        : 'https://www.google.com/maps/search/?api=1&query=' + encodeURIComponent(s.mapa);
      let fila = molde[0]
        .split('{{CIUDAD}}').join(esc(sucursales.length > 1 ? 'Sucursal ' + (i + 1) : 'Ubicacion'));
      fila = fila.replace(/href="[^"]*maps\/search[^"]*"/, 'href="' + destino + '"');
      if (s.texto) {
        fila = fila.split('{{UBICACION_TEXTO}}').join(esc(corta(s.texto, 90)));
      } else {
        fila = fila.replace(/<span>\{\{UBICACION_TEXTO\}\}<\/span>\s*/, '');
      }
      return fila;
    });
    h = h.replace(LI_UBICACION, () => filas.join('\n'));
