  const molde = h.match(LI_TELEFONO);
  if (molde) {
    // El de WhatsApp va primero y conserva su etiqueta; los demas son
    // telefonos del negocio y se rotulan aparte.
    const filas = [molde[0]].concat(telefonos.map((t, i) => molde[0]
      .split('{{ETIQ_2}}').join(esc(telefonos.length > 1 ? 'Telefono ' + (i + 1) : 'Telefono'))
      // Se cambia el enlace entero, no solo el dominio: dejando el
