pon('ETIQ_2', 'WhatsApp', 18);
pon('ETIQ_3', 'Horario', 18);
// El horario real del cliente manda sobre el que redacte la IA.
pon('HORARIO_1', j.contacto.horario || c.horario || 'Lunes a sabado, 9:00 a 19:00', 52);
pon('TEL_DISPLAY', j.contacto.tel_display, 24);
pon('CIUDAD', j.perfil.ciudad || '', 40);
pon('CTA_PRIMARIO', portada.cta_primario || 'Escribenos', 22);

// La direccion va dentro de la URL del mapa: si no se codifica, el iframe
