  .replace(/>/g, '&gt;').replace(/"/g, '&quot;');

// --- pie ---
let h = j.piezas.footer;
const f = cierre.footer || {};
const pon = (tok, val, max) => { h = h.split('{{' + tok + '}}').join(esc(corta(val, max))); };
pon('NOMBRE_NEGOCIO', j.marca.nombre_negocio, 40);
pon('TAGLINE', portada.tagline || j.perfil.propuesta_valor, 46);
pon('FOOTER_DESC', f.desc || j.perfil.propuesta_valor, 180);
pon('FOOTER_COL1_TIT', f.col1 || 'Navegacion', 22);
pon('FOOTER_COL2_TIT', f.col2 || 'Contacto', 22);
const NAV_ALT = ['Inicio', 'Servicios', 'Galeria', 'Contacto'];
const nav = Array.isArray(portada.nav) ? portada.nav : [];
for (let i = 1; i <= 4; i++) pon('NAV_' + i, nav[i - 1] || NAV_ALT[i - 1], 16);
