const j = $('Armar footer').first().json;
const D = j.diseno;
const portada = (() => { const p = $('Copy portada (IA)').first().json; return p.output ?? p; })();

// ---------- 1. CSS: marca y tipografia ----------
let css = String(j.css || '');

// Color. Se reescribe TODA la paleta, no solo los acentos: fondos, superficies,
// texto, bordes y detalles salen del logo del negocio. Y si el tema es claro,
// los neutros se invierten, con lo que la pagina entera cambia de piel sin
// tocar una sola regla de maquetacion.
//
