//                  el icono de WhatsApp). Se resuelven uno por uno al final.
const C = D.color;

const aRgb = (h) => {
  let s = String(h).replace('#', '');
  if (s.length === 3) s = s[0] + s[0] + s[1] + s[1] + s[2] + s[2];
  const n = parseInt(s, 16);
  // Se asigna antes de devolver: el analisis estatico de n8n confunde un
  // `return [` dentro de una funcion auxiliar con la salida del nodo.
  return { r: (n >> 16) & 255, g: (n >> 8) & 255, b: n & 255 };
};
const aHsl = (hex) => {
  const c = aRgb(hex);
  const r0 = c.r / 255, g0 = c.g / 255, b0 = c.b / 255;
  const mx = Math.max(r0, g0, b0), mn = Math.min(r0, g0, b0);
  const l = (mx + mn) / 2;
  if (mx === mn) return { h: 0, s: 0, l };
  const d = mx - mn;
  const s = l > 0.5 ? d / (2 - mx - mn) : d / (mx + mn);
  let h;
  if (mx === r0) h = ((g0 - b0) / d + (g0 < b0 ? 6 : 0)) / 6;
  else if (mx === g0) h = ((b0 - r0) / d + 2) / 6;
  else h = ((r0 - g0) / d + 4) / 6;
  return { h, s, l };
};
const aHex = (h, s, l) => {
  h = ((h % 1) + 1) % 1; s = Math.min(1, Math.max(0, s)); l = Math.min(1, Math.max(0, l));
  const f = (n) => {
    const k = (n + h * 12) % 12;
    const a = s * Math.min(l, 1 - l);
    const v = l - a * Math.max(-1, Math.min(k - 3, Math.min(9 - k, 1)));
    return Math.round(v * 255).toString(16).padStart(2, '0');
  };
  return '#' + f(0) + f(8) + f(4);
};

// --- 1a. acentos de la plantilla -> acentos de la marca ---
