  '#ff5468': C.acento_claro,    // su version clara, para brillos y hover
  '#ff7887': C.acento_claro,    // otra mas clara todavia
  '#9f1022': C.acento_oscuro,   // su version oscura, para los degradados
  '#c31830': C.acento_oscuro,   // otra oscura
  '#c7a970': C.detalle,         // el dorado de los detalles finos
  '#e7cf9c': C.detalle,         // el dorado claro
  '#7fa183': C.apoyo,           // el verde salvia de las pastillas de categoria
};

// --- 1b. las variables de tema ---
// La plantilla trae su propio sistema de temas, hecho a conciencia:
//   :root                                el juego por defecto
//   @media (prefers-color-scheme:light)  el juego claro
//   --photo-*                            las zonas sobre fotografia, FIJAS
// Las --photo-* no se tocan jamas: debajo siempre hay una foto oscurecida y
// su texto va claro pase lo que pase.
//
// Antes esto barria toda la hoja invirtiendo luminosidades a mano. Con la
// plantilla nueva eso peleaba contra su propio sistema y dejaba la pagina a
// medio invertir. Ahora solo se escriben los valores de cada bloque, que es
// como el CSS esta pensado para cambiarse.
const CHROME = (c) => ({
  '--ink': c.fondo,
  '--ink-2': c.fondo_2,
  '--ink-3': c.fondo,
  '--panel': c.fondo_2,
  '--paper': c.texto,
  '--paper-muted': c.texto_2,
  '--text': c.texto,
  '--muted': c.texto_2,
});
const rgbaDe = (hex, a) => {
  const q = aRgb(hex);
  return 'rgba(' + q.r + ', ' + q.g + ', ' + q.b + ', ' + a + ')';
};
const LINEAS = (c) => ({
  '--line': rgbaDe(c.texto, 0.09),
  '--line-2': rgbaDe(c.texto, 0.16),
  '--line-3': rgbaDe(c.texto, 0.26),
  '--ghost': rgbaDe(c.texto, 0.03),
  '--wash-1': rgbaDe(c.texto, 0.045),
});

// Reescribe las declaraciones de un bloque, saltandose las --photo-*
const pintaBloque = (bloque, c) => {
  const vals = Object.assign({}, CHROME(c), LINEAS(c));
  return bloque.replace(/(\n\s*)(--[a-z0-9-]+)(\s*:\s*)([^;]+);/g, (m, sp, nom, sep, val) => {
    if (nom.indexOf('--photo-') === 0) return m;          // zonas con foto: intactas
    return vals[nom] !== undefined ? sp + nom + sep + vals[nom] + ';' : m;
  });
};

// Los DOS bloques llevan la MISMA paleta: la del tema que se decidio por el
// giro y el logo. La plantilla cambia de tema segun la preferencia del
// sistema, y eso para una landing de negocio es un problema: el mismo enlace
// se veria oscuro en un telefono y claro en otro, con dos marcas distintas.
// Peor todavia: los acentos se calculan contra UN fondo, asi que en el tema
// que no toca dejan de contrastar. Aqui la pagina se ve igual en todos lados.
{
  const i = css.indexOf(':root {');
  const f = css.indexOf('}', i);
  css = css.slice(0, i) + pintaBloque(css.slice(i, f), C) + css.slice(f);
}
{
  const m = css.match(/@media \(prefers-color-scheme: light\)\s*\{\s*:root \{/);
  if (m) {
    const i = m.index + m[0].length;
    const f = css.indexOf('}', i);
    css = css.slice(0, i) + pintaBloque(css.slice(i, f), C) + css.slice(f);
  }
}

// --- 1b-bis. el barrido, ya solo para los acentos ---
// Neutro o color de marca se decide por CROMA (cuanto se separan el canal mas
// alto y el mas bajo), no por la saturacion HSL. La saturacion miente en los
// extremos: el crema #f8f3ed con el que la plantilla escribe todos sus textos
// da saturacion 0.44 -parece un color- cuando en pantalla es casi blanco. Con
// ese criterio el texto se quedaba claro en el tema claro, y la pagina salia
// con letras blancas sobre fondo blanco.
const osc = D.tema === 'oscuro';
const Hm = aHsl(D.color_base).h;
const INTOCABLES = new Set(['#25d366', '#000', '#000000']);
// Los neutros ya quedaron resueltos arriba, en las variables. Aqui solo se
// cambian los colores de marca, que si viven sueltos por toda la hoja.
const destino = (hex) => ACENTOS[hex.toLowerCase()] || null;

// --- el blanco que NO es un neutro cualquiera ---
// Tres reglas escriben en blanco sobre un fondo de acento: el boton primario,
// el nodo activo de la linea de tiempo y la seleccion de texto. Ahi el blanco
// no se invierte con el resto: va el color que de verdad contrasta contra el
// acento de ESTA marca, que segun el caso es blanco o negro.
//
// Se marca ANTES del barrido con una senal que ningun color puede tener y se
// resuelve DESPUES. Al reves no funciona: el barrido volveria a transformar el
// color recien puesto y en tema claro lo dejaria del reves.
const SENAL = '__HW_SOBRE_ACENTO__';
css = css.replace(/color: #fff;/g, 'color: ' + SENAL + ';');

// hexadecimales
css = css.replace(/#[0-9a-fA-F]{6}\b|#[0-9a-fA-F]{3}\b/g, (m) => destino(m) || m);

// triples de rgb()/rgba(). El 0,0,0 se salta: son las sombras.
css = css.replace(/(rgba?\(\s*)(\d{1,3})\s*,\s*(\d{1,3})\s*,\s*(\d{1,3})/g, (m, pre, r, g, b) => {
  if (+r === 0 && +g === 0 && +b === 0) return m;
  if (+r === 37 && +g === 211 && +b === 102) return m;    // verde de WhatsApp
  if (+r === 18 && +g === 140 && +b === 126) return m;    // su verde oscuro
  const hex = '#' + [r, g, b].map((x) => (+x).toString(16).padStart(2, '0')).join('');
  // El blanco puro si se invierte cuando va en rgba(): ahi son bordes y
  // brillos sobre superficie oscura, y en tema claro tienen que ser oscuros.
  // Como hexadecimal solido se deja, que es el icono de WhatsApp.
  const nuevo = destino(hex);
  if (!nuevo) return m;
  const q = aRgb(nuevo);
  return pre + q.r + ',' + q.g + ',' + q.b;
});

// --- 1c. la senal se convierte en el color definitivo ---
css = css.split(SENAL).join(C.sobre_acento);

// Sobre fotografia, el color explicito.
// La plantilla redefine --text dentro de .hero, .loader y demas, pero el
// color de esos textos se HEREDA de <body>, que ya lo resolvio con el --text
// de :root. Redefinir la variable despues no cambia un color ya heredado, asi
// que el cargador salia con letras oscuras sobre fondo oscuro.
//
// Se pone en el CONTENEDOR, no en cada texto: asi el color se hereda hacia
// dentro y alcanza tambien a los enlaces, que la plantilla declara como
// `a { color: inherit }` -y esa regla le gana a un :where() sobre el propio
// enlace-. Como es el contenedor, no compite con los elementos que si traen
// color propio (.tag, .text-gold, los botones): esos ni siquiera heredan.
//
// Y con ellos el ACENTO de esas zonas. La plantilla ya separo los neutros de
// fotografia con --photo-*, pero no el acento, y ahi falla en tema claro: el
// acento se calcula para leerse sobre el fondo de la PAGINA, que es claro, asi
// que sale oscuro; y encima del velo oscuro del encabezado no se distingue.
// Lo que va en las zonas con foto es el acento de la paleta OSCURA, que es
// justo el calculado para leerse sobre fondo oscuro. En tema oscuro los dos
// coinciden, asi que ponerlo siempre no cambia nada.
const OS = D.color_oscuro;
css += '\n/* --- sobre fotografia: texto y acento claros --- */\n'
  + '.hero,.site-header,.loader,.lightbox,.has-bg,.parallax-banner{'
  + 'color:var(--photo-text);'
  + '--red:' + OS.acento + ';'
  + '--red-2:' + OS.acento_claro + ';'
  + '--red-dark:' + OS.acento_oscuro + ';'
  + '--sage:' + OS.apoyo + ';'
  + '--gold:' + OS.detalle + ';'
  + '}\n';

// Tipografia. La plantilla trae Cormorant para titulos e Inter para texto,
// escritos a mano en una docena de sitios. Se cambian por variables y se
// definen una sola vez, asi el trio que escogio el agente manda en toda la
// pagina sin tocar una sola regla de maquetacion.
css = css.replace(/"Cormorant Garamond",\s*serif/gi, 'var(--hw-display)');
css = css.replace(/"Inter",\s*system-ui[^;]*/gi, 'var(--hw-texto)');
css = css.replace(/"Inter",\s*sans-serif/gi, 'var(--hw-texto)');
css = css.replace(/:root\s*\{/, ':root{'
  + '\n  --hw-display: ' + D.pila_display + ';'
  + '\n  --hw-texto: ' + D.pila_texto + ';'
  + '\n  --hw-acento: ' + D.pila_acento + ';');

// La TERCERA tipografia, la de acento, va en las etiquetas chicas en
// mayusculas: los rotulos de seccion, las pastillas de categoria, los datos
// de contacto y del pie, y el menu. Es el tercer nivel que separa una pagina
// cuidada de una hecha con una sola fuente.
//
// Con :where() para no ganarle por especificidad a nada de la plantilla.
css += '\n/* --- tercera tipografia: etiquetas y rotulos --- */\n'
  + ':where(.eyebrow,.tag,.contact-label,.hero-social-label,.hero-typewriter-label,'
  + '.brand-tagline,.nav-link,.footer-col h4,.footer-bottom-tag,.loader-tagline)'
  + '{font-family:var(--hw-acento)}\n';

