  + ':where(img,svg,video,iframe){max-width:100%}\n'
  + '@media (max-width:640px){\n'
  + '  :where(.hero-title){font-size:clamp(1.9rem,8.2vw,2.6rem)!important;line-height:1.12!important}\n'
  + '  :where(.section-title,.parallax-content h2){font-size:clamp(1.5rem,6.4vw,2rem)!important;line-height:1.18!important}\n'
  + '}\n';

// ---------- 3. JS: las palabras del typewriter ----------
let js = String(j.js || '');
const CICLO_ALT = ['calidad', 'buen precio', 'a tiempo', 'sin complicaciones'];
const ciclo = (Array.isArray(portada.ciclo) ? portada.ciclo : [])
  .map((s) => String(s || '').replace(/["\\\n\r]/g, '').trim()).filter(Boolean);
for (let i = 1; i <= 4; i++) {
