}

// ---------- 4. Pegar los bloques ----------
const B = j.bloques;
const ORDEN = ['cabeza', 'nav', 'abreMain', 'hero', 'servicios', 'banner1', 'ventajas',
  'resultados', 'banner2', 'galeria', 'contacto', 'cierraMain', 'footer', 'flotantes', 'pie'];
