// ============================================================
//  PRUEBA 2 · REVISAR ANTES DE PUBLICAR
//
//  Lo ultimo antes de GitHub. Si algo de esto falla la pagina NO se sube:
//  vale mas que el flujo se detenga y quede el error registrado, a que el
//  cliente reciba un enlace con {{HERO_TIT_1}} escrito en la portada.
//
//  Cada revision de aqui corresponde a un defecto que ya salio publicado
//  alguna vez en el flujo anterior.
// ============================================================
// El estado acumulado viene del bloque anterior POR NOMBRE, no de $json:
// entre un bloque y otro hay agentes de IA que reemplazan el item y se
// llevarian por delante piezas, bloques y todo lo demas.
const j = $('Ensamblar pagina').first().json;
const html = String(j.html || '');
const fallas = [];

// 1. huecos sin rellenar. El mas caro de todos: se ve a simple vista.
const huecos = [...new Set([...html.matchAll(/\{\{([A-Z_0-9]+)\}\}/g)].map((m) => m[1]))];
if (huecos.length) fallas.push('huecos sin rellenar: ' + huecos.join(', '));

// 2. rutas locales que no existen en el repo. El repo es un solo index.html,
//    asi que cualquier src o href a css/, js/ o imagenes/ queda roto.
const locales = [...html.matchAll(/(?:src|href)="((?:\.\/)?(?:css|js|assets|imagenes|img|nuevas)\/[^"]+)"/gi)]
  .map((m) => m[1]);
if (locales.length) fallas.push('archivos locales sin embeber: ' + [...new Set(locales)].join(', '));

