//    Salvo las que el propio JS de la plantilla rellena al vuelo, como la del
//    visor de la galeria: nace vacia a proposito y se llena al abrir una foto.
//    Se reconocen porque su id aparece en el script de la pagina.
const vacias = [...html.matchAll(/<img[^>]*src=""[^>]*>/gi)].filter((m) => {
  const id = (m[0].match(/id="([^"]+)"/) || [])[1];
  return !(id && html.indexOf("'" + id + "'") >= 0) && !(id && html.indexOf('"' + id + '"') > html.indexOf('<script'));
