if (vacias.length) fallas.push(vacias.length + ' imagenes con src vacio');

// 4. el telefono del cliente tiene que estar, y ser el suyo
const tel = String(j.contacto.whatsapp || '');
if (!tel || tel.length < 10) fallas.push('el telefono no quedo bien: "' + tel + '"');
else if (html.indexOf('wa.me/' + tel) < 0) fallas.push('el enlace de WhatsApp no apunta al telefono del cliente');

// 5. nada de otro cliente. La plantilla se diseño para un negocio real y su
//    nombre no puede acabar en la pagina de otro.
// OJO con lo que se mete aqui: solo nombres que NO puedan aparecer
// legitimamente. "Cormorant Garamond" estuvo en esta lista y tiraba
// publicaciones enteras, porque el agente de tipografia puede elegirla: esta
// en el catalogo y es la display por defecto de la familia "lujo".
const RASTROS = /nufax|lorem ipsum/i;
const rastro = html.match(RASTROS);
if (rastro) fallas.push('quedo un rastro de la plantilla original: "' + rastro[0] + '"');

