//    que este el nombre o el arranque que si cabe.
const nombre = String(j.marca.nombre_negocio || '').trim();
if (nombre && html.indexOf(nombre) < 0) {
  const cabe = nombre.length <= 40 ? nombre : (() => {
    const c = nombre.slice(0, 40);
    const e = c.lastIndexOf(' ');
    return e > 12 ? c.slice(0, e) : c;
  })();
  if (html.indexOf(cabe) < 0) {
    fallas.push('el nombre del negocio no aparece en la pagina, ni siquiera recortado: "'
      + cabe + '"');
  }
}

// 6b. el nombre del repo y del dominio. GitHub y Vercel solo aceptan
//     minusculas, numeros y guiones, y sin esto la publicacion falla con un
//     422 que no dice gran cosa.
const rs = String(j.repo_slug || '');
if (!/^[a-z0-9][a-z0-9-]{1,59}$/.test(rs)) {
  fallas.push('el nombre para GitHub y Vercel no es valido: "' + rs + '"');
}

// 7. tamano razonable. Muy chica = se perdio un bloque. Muy grande = no
//    cabe en un commit de la API de GitHub sin problemas.
if (html.length < 24000) fallas.push('la pagina salio muy corta (' + html.length + ' car): falta algun bloque');
if (html.length > 1400000) fallas.push('la pagina salio muy pesada (' + html.length + ' car)');

// 8. los bloques tienen que estar todos y en su sitio
// Se buscan por PREFIJO: la plantilla anade clases a varias secciones
// (has-bg, --alt) y un marcador con la clase cerrada dejaria de encontrarlas.
const SENAS = { nav: '<header class="site-header"', hero: 'class="hero"', servicios: 'id="servicios"',
  ventajas: 'class="why-us', galeria: 'id="galeria"', contacto: 'id="contacto"',
  footer: '<footer class="site-footer"', flotantes: 'whatsapp-float' };
const perdidos = Object.entries(SENAS).filter(([, s]) => html.indexOf(s) < 0).map(([k]) => k);
if (perdidos.length) fallas.push('bloques que no llegaron a la pagina: ' + perdidos.join(', '));

if (fallas.length) {
  // Todo en UNA linea: n8n corta el mensaje en el primer salto y se quedaba
  // en "no paso la revision" sin decir por que, que obliga a reproducirlo a
  // mano para averiguarlo.
  throw new Error('La pagina no paso la revision, no se publica: ' + fallas.join(' | '));
}

// Los nodos de publicacion (GitHub, Vercel, Postgres, WhatsApp) leen sus
// datos de AQUI, que es el ultimo nodo antes de publicar. Van en la raiz del
// json a proposito: si cada uno tuviera que ir a buscarlos a un nodo distinto
// del flujo, bastaria renombrar o mover un nodo para romper la publicacion
// entera, que es exactamente lo que paso al reestructurar este workflow.
const sitio = (() => {
  try { return $('Reservar sitio').first().json.sitio_id; } catch (e) { return j.sitio_id; }
})();

return [{
  json: {
    ...j,
    revision_ok: true,
    slug: j.slug_final,
    // El repo de GitHub y el dominio de Vercel se llaman como el negocio,
    // todo pegado: "Casana Natural Health" -> casananaturalhealth.vercel.app
    repo_slug: j.repo_slug,
    nombre_negocio: nombre,
    sitio_id: sitio,
    telefono: j.telefono,
    html,
    // GitHub recibe el contenido en base64, no en texto plano
    html_b64: Buffer.from(html, 'utf8').toString('base64'),
    resumen: {
      bytes: html.length,
      tipografia: j.diseno.fuente_display + ' + ' + j.diseno.fuente_texto,
      familia_visual: j.diseno.familia_visual,
      acento: j.marca.paleta.acento,
      fotos_usadas: [...new Set((html.match(/https:\/\/images\.pexels\.com[^"']+/g) || []))].length,
    },
  },
}];

// ============================================================
//  PRUEBA 2 · ELEGIR EL ENLACE QUE SE LE MANDA AL CLIENTE
//
//  Vercel le pone varias direcciones al mismo sitio:
//      newfit-gimnasio.vercel.app                      <- la buena
//      newfit-gimnasio-helloweb100-5644s-projects...   <- con el equipo pegado
//      newfit-gimnasio-git-main-helloweb100...         <- la de la rama
//  Mandar por WhatsApp una de las largas da la impresion de enlace temporal
//  de pruebas, no de la pagina de su negocio.
//
//  ANTES esto se ARMABA a mano: se pegaba el nombre del proyecto con
//  ".vercel.app" y se daba por hecho que Vercel se lo habia asignado. Cuando
//  Vercel elegia otro nombre -porque el que queriamos ya estaba ocupado- el
//  cliente recibia un enlace que no abria. Por eso ahora se PREGUNTA: el nodo
//  'Vercel dominios' trae los dominios reales del proyecto y aqui solo se
//  escoge entre ellos.
//
//  Va ANTES de guardar en la base para que la direccion que se registra y la
//  que recibe el cliente sean la misma.
// ============================================================
const repo = $('Revisar pagina').first().json.repo_slug;

const normaliza = (a) => String((typeof a === 'string' ? a : (a && (a.name || a.domain)) || ''))
  .replace(/^https?:\/\//, '')
  .replace(/\/+$/, '')
  .trim()
  .toLowerCase();

// --- 1) los dominios que Vercel dice que tiene el proyecto ---
const deVercel = (() => {
  try {
    const r = $('Vercel dominios').first().json;
    return Array.isArray(r && r.domains) ? r.domains : [];
  } catch (e) { return []; }
})();

// --- 2) los alias del despliegue, como respaldo ---
const delDespliegue = (() => {
  try {
    const v = $('Vercel desplegar').first().json;
    return [].concat(v.alias || [], v.automaticAliases || [], v.url || []);
  } catch (e) { return []; }
})();

const candidatos = [].concat(deVercel, delDespliegue)
  .map(normaliza)
  .filter((a) => a.endsWith('.vercel.app'))
  // las de rama no sirven para mandar: cambian con cada push
  .filter((a) => a.indexOf('-git-') < 0);

const unicos = candidatos.filter((a, i) => candidatos.indexOf(a) === i);

// El ideal es el que se llama como el proyecto. Si no esta, la mas corta de
// las que Vercel si confirmo, que es siempre la mas presentable.
const ideal = repo + '.vercel.app';
const elegido = unicos.indexOf(ideal) >= 0
  ? ideal
  : unicos.slice().sort((a, b) => a.length - b.length)[0] || null;

// Si Vercel no devolvio ninguna -API caida, permisos- se arma la esperada y
// se deja anotado que nadie la confirmo, para poder revisarlo despues.
const destino = elegido || ideal;

return [{
  json: {
    deployment_url: 'https://' + destino,
    enlace_confirmado_por_vercel: !!elegido,
    enlace_es_el_ideal: destino === ideal,
    enlaces_de_vercel: unicos,
  },
}];

